import pulp

# Data from the problem
shipments = {
    'S1': [('H5', 8), ('H4', 7), ('H1', 4), ('H2', 8), ('H3', 8)],
    'S2': [('H5', 5), ('H3', 3), ('H2', 8), ('H1', 1), ('H4', 10)],
    'S3': [('H2', 1), ('H1', 9), ('H5', 2), ('H3', 2), ('H4', 7)],
    'S4': [('H1', 5), ('H3', 5), ('H5', 4), ('H4', 3), ('H2', 10)],
    'S5': [('H3', 6), ('H2', 7), ('H1', 3), ('H4', 6), ('H5', 7)]
}

shipment_ids = list(shipments.keys())
hub_ids = ['H1', 'H2', 'H3', 'H4', 'H5']

# Step indices for each shipment
steps = {}
for s in shipment_ids:
    steps[s] = list(range(len(shipments[s])))

# Create model
model = pulp.LpProblem("JobShopScheduling", pulp.LpMinimize)

# Decision variables: start time of shipment s at step j
x = {}
for s in shipment_ids:
    for j in steps[s]:
        x[(s, j)] = pulp.LpVariable(f'x_{s}_{j}', lowBound=0, cat='Continuous')

# Makespan variable
C_max = pulp.LpVariable('C_max', lowBound=0, cat='Continuous')

# Binary variables for sequencing at each hub
z = {}
for h in hub_ids:
    for i in shipment_ids:
        for k in shipment_ids:
            if i < k:  # avoid duplicates and self
                z[(i, k, h)] = pulp.LpVariable(f'z_{i}_{k}_{h}', cat='Binary')

# Objective: minimize makespan
model += C_max

# Precedence constraints within each shipment
for s in shipment_ids:
    for j in range(len(steps[s]) - 1):
        model += x[(s, j)] + shipments[s][j][1] <= x[(s, j + 1)]

# Makespan definition constraints
for s in shipment_ids:
    last_step = len(steps[s]) - 1
    model += x[(s, last_step)] + shipments[s][last_step][1] <= C_max

# Disjunctive constraints for each hub
M = 10000  # large constant

for h in hub_ids:
    # Find all (shipment, step) pairs that use this hub
    tasks_at_hub = []
    for s in shipment_ids:
        for j in steps[s]:
            if shipments[s][j][0] == h:
                tasks_at_hub.append((s, j))

    # For each pair of tasks at this hub, add disjunctive constraints
    for idx1 in range(len(tasks_at_hub)):
        for idx2 in range(idx1 + 1, len(tasks_at_hub)):
            s1, j1 = tasks_at_hub[idx1]
            s2, j2 = tasks_at_hub[idx2]

            # Ensure s1 < s2 for consistent binary variable indexing
            if s1 < s2:
                var_name = (s1, s2, h)
            else:
                var_name = (s2, s1, h)
                # swap to match variable key order
                s1, s2 = s2, s1
                j1, j2 = j2, j1

            # s1 before s2 if z = 1
            model += x[(s1, j1)] + shipments[s1][j1][1] <= x[(s2, j2)] + M * (1 - z[var_name])
            # s2 before s1 if z = 0
            model += x[(s2, j2)] + shipments[s2][j2][1] <= x[(s1, j1)] + M * z[var_name]

# Solve
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Output results
print("Status:", pulp.LpStatus[model.status])
print("Optimal makespan:", pulp.value(C_max))
print("\nStart times for each shipment at each step:")
for s in shipment_ids:
    print(f"\n{s}:")
    for j in steps[s]:
        hub, time = shipments[s][j]
        print(f"  Step {j}: Hub {hub}, processing {time}h, starts at {pulp.value(x[(s, j)])}")

print("\nSequence at each hub (by start time):")
for h in hub_ids:
    tasks = []
