import pulp

# Data
patients = ['A', 'B', 'C']
ops = [1, 2, 3]

# Device needed: m[p][j]
m = {
    'A': {1: 'X', 2: 'Z', 3: 'Y'},
    'B': {1: 'X', 2: 'Y', 3: 'Z'},
    'C': {1: 'Z', 2: 'X', 3: 'Y'}
}

# Duration: d[p][j]
d = {
    'A': {1: 2, 2: 4, 3: 6},
    'B': {1: 1, 2: 2, 3: 3},
    'C': {1: 10, 2: 9, 3: 10}
}

# Big M: sum of all durations
M = sum(d[p][j] for p in patients for j in ops)

# Model
model = pulp.LpProblem("HospitalTestScheduling", pulp.LpMinimize)

# Variables
S = {}
for p in patients:
    for j in ops:
        S[(p, j)] = pulp.LpVariable(f"S_{p}_{j}", lowBound=0, cat='Continuous')

C_max = pulp.LpVariable("C_max", lowBound=0, cat='Continuous')

# Binary variables for ordering on each machine
# List all operations with their machine
op_list = []
for p in patients:
    for j in ops:
        op_list.append((p, j, m[p][j], d[p][j]))

y_vars = {}
# Create binary for each unordered pair on same machine
for idx1 in range(len(op_list)):
    for idx2 in range(idx1 + 1, len(op_list)):
        p1, j1, machine1, dur1 = op_list[idx1]
        p2, j2, machine2, dur2 = op_list[idx2]
        if machine1 == machine2:
            y_vars[(p1, j1, p2, j2)] = pulp.LpVariable(
                f"y_{p1}_{j1}_{p2}_{j2}", cat='Binary'
            )

# Objective
model += C_max

# Precedence constraints
for p in patients:
    model += S[(p, 1)] + d[p][1] <= S[(p, 2)]
    model += S[(p, 2)] + d[p][2] <= S[(p, 3)]

# Machine constraints
for (p1, j1, p2, j2), y in y_vars.items():
    machine = m[p1][j1]  # same as m[p2][j2]
    # If y = 1: (p1,j1) before (p2,j2)
    model += S[(p1, j1)] + d[p1][j1] <= S[(p2, j2)] + M * (1 - y)
    # If y = 0: (p2,j2) before (p1,j1)
    model += S[(p2, j2)] + d[p2][j2] <= S[(p1, j1)] + M * y

# Makespan constraints
for p in patients:
    model += S[(p, 3)] + d[p][3] <= C_max

# Solve
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Output
print("Status:", pulp.LpStatus[model.status])
print("Optimal makespan:", pulp.value(C_max))
print("\nSchedule:")
for p in patients:
