import pulp
import itertools

# Data
outlets = ['A', 'B', 'C', 'D']
techs = [1, 2, 3, 4]

# Discharge coeff
d = {'A': 0.986, 'B': 2.241, 'C': 1.736, 'D': 1.11}
# Flow rate
f = {'A': 214.015, 'B': 51.386, 'C': 237.741, 'D': 242.512}

# Efficiencies
r = {1: 0.82, 2: 0.56, 3: 0.76, 4: 0.13}
remaining = {j: 1 - r[j] for j in techs}

# Cost matrix c[i][j]
c = {
    'A': {1: 108.412, 2: 19.541, 3: 57.348, 4: 171.184},
    'B': {1: 96.728, 2: 162.269, 3: 136.84, 4: 197.7},
    'C': {1: 123.136, 2: 190.508, 3: 179.371, 4: 126.404},
    'D': {1: 146.662, 2: 105.908, 3: 167.808, 4: 114.096}
}

# Baseline TDS
baseline = {i: d[i] * f[i] for i in outlets}
total_baseline = sum(baseline.values())
P = 0.649
target = total_baseline * (1 - P)

# All subsets of {1,2,3,4}
subsets = []
for mask in range(16):
    S = tuple(j for j in techs if (mask >> (j-1)) & 1)
    subsets.append(S)

# Remaining TDS fraction after subset S
R_S = {}
for S in subsets:
    rem = 1.0
    for j in S:
        rem *= remaining[j]
    R_S[S] = rem

# Cost per unit flow for subset S at outlet i
cost_S = {}
for i in outlets:
    cost_S[i] = {}
    for S in subsets:
        cost_S[i][S] = sum(c[i][j] for j in S)

# LP Model
model = pulp.LpProblem("WaterTreatment", pulp.LpMinimize)

# Variables: z[i][S] = fraction of flow at outlet i treated by subset S
z = {}
for i in outlets:
    for S in subsets:
        z[(i, S)] = pulp.LpVariable(f"z_{i}_{S}", lowBound=0, upBound=1)

# Objective: total cost
model += pulp.lpSum(f[i] * cost_S[i][S] * z[(i, S)] for i in outlets for S in subsets)

# Constraints: fractions sum to 1 for each outlet
for i in outlets:
    model += pulp.lpSum(z[(i, S)] for S in subsets) == 1

# TDS constraint: total after treatment <= target
model += pulp.lpSum(f[i] * d[i] * R_S[S] * z[(i, S)] for i in outlets for S in subsets) <= target

# Solve
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Output
print("Status:", pulp.LpStatus[model.status])
print("Total cost:", pulp.value(model.objective))
print("\nFlow fractions per outlet:")
for i in outlets:
    for S in subsets:
        val = pulp.value(z[(i, S)])
        if val > 1e-6:
            print(f"  {i}, subset {S}: {val:.4f}")
print("\nTDS after treatment:")
tds_total = 0
for i in outlets:
    tds_i = sum(f[i] * d[i] * R_S[S] * pulp.value(z[(i, S)]) for S in subsets)
    tds_total += tds_i
    print(f"  {i}: {tds_i:.3f}")
print(f"Total TDS: {tds_total:.3f}, target max: {target:.3f}")

