                        model += S[(j2, k2)] + p2 <= S[(j1, k1)] + M * var
                    # else handled by symmetry

# 3. Makespan definition
for j in jobs:
    model += C_max >= S[(j, num_ops-1)] + operations[j][num_ops-1][1]

# Solve
