S = {}
for i in patients:
    for j in operations:
        S[(i, j)] = pulp.LpVariable(f"S_{i}_{j}", lowBound=0, cat='Continuous')

C_max = pulp.LpVariable("C_max", lowBound=0, cat='Continuous')

# Binary variables for disjunctive constraints
y = {}
# Only create for pairs (i,k) with i < k and same equipment
for i in patients:
    for k in patients:
        if i >= k:
            continue
        for j in operations:
            for l in operations:
                eq_ij = requirements[i][j-1][0]
                eq_kl = requirements[k][l-1][0]
                if eq_ij == eq_kl:
                    y[(i, k, j, l)] = pulp.LpVariable(f"y_{i}_{k}_{j}_{l}", cat='Binary')

# Objective
model += C_max

# Precedence constraints within each patient
for i in patients:
    for j in range(1, 4):  # j = 1,2,3
        dur = requirements[i][j-1][1]
        model += S[(i, j)] + dur <= S[(i, j+1)]

# Disjunctive constraints
M = 1000  # Big-M
for i in patients:
    for k in patients:
        if i >= k:
            continue
        for j in operations:
            for l in operations:
                eq_ij = requirements[i][j-1][0]
                eq_kl = requirements[k][l-1][0]
                if eq_ij == eq_kl:
                    dur_ij = requirements[i][j-1][1]
                    dur_kl = requirements[k][l-1][1]
                    # If y = 1: S_ij + dur_ij <= S_kl
                    model += S[(i, j)] + dur_ij <= S[(k, l)] + M * (1 - y[(i, k, j, l)])
                    # If y = 0: S_kl + dur_kl <= S_ij
                    model += S[(k, l)] + dur_kl <= S[(i, j)] + M * y[(i, k, j, l)]

# Makespan definition
for i in patients:
    last_op_dur = requirements[i][3][1]
    model += S[(i, 4)] + last_op_dur <= C_max

# Solve
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Output
