for (i, j), d in list(dist.items()):
    if i > j:
        dist[(j, i)] = d

hubs = list(range(1, 8))

# Create initial model
model = pulp.LpProblem("TSP", pulp.LpMinimize)

# Variables
x = {}
for i in hubs:
    for j in hubs:
        if i < j:
            x[i, j] = pulp.LpVariable(f"x_{i}_{j}", cat='Binary')

# Objective
model += pulp.lpSum(dist[i, j] * x[i, j] for i, j in x.keys())

# Degree constraints: each hub degree = 2
for k in hubs:
    incident_edges = []
    for i, j in x.keys():
        if i == k or j == k:
            incident_edges.append(x[i, j])
    model += pulp.lpSum(incident_edges) == 2

# Subtour elimination loop
while True:
    model.solve(pulp.HiGHS(msg=False, timeLimit=120))

    # Get selected edges
    tour_edges = []
    for (i, j), var in x.items():
        if pulp.value(var) > 0.5:
            tour_edges.append((i, j))

    # Build graph adjacency to find connected components
    adj = {h: [] for h in hubs}
    for i, j in tour_edges:
        adj[i].append(j)
        adj[j].append(i)

    # Find connected components (subtours)
    visited = set()
    subtours = []
    for h in hubs:
        if h not in visited:
            stack = [h]
            comp = []
            while stack:
                node = stack.pop()
                if node not in visited:
                    visited.add(node)
                    comp.append(node)
                    for nb in adj[node]:
                        if nb not in visited:
                            stack.append(nb)
            subtours.append(comp)

    if len(subtours) == 1:
        break  # One tour covering all nodes

    # Add subtour elimination constraints for each subtour
    for subtour in subtours:
        if 2 <= len(subtour) <= len(hubs) - 1:
            edges_in_subtour = []
            for i, j in x.keys():
                if i in subtour and j in subtour:
                    edges_in_subtour.append(x[i, j])
            model += pulp.lpSum(edges_in_subtour) <= len(subtour) - 1

# Output results
print("Optimal tour edges:")
for (i, j), var in x.items():
    if pulp.value(var) > 0.5:
        print(f"Hub {i} -- Hub {j} : {dist[i, j]} km")

total_distance = pulp.value(model.objective)
print(f"\nTotal inspection tour distance: {total_distance:.1f} km")
